const body = $input.first().json.body || $input.first().json;

let telefono = '';
let mensaje = '';
let nombre = '';
let remoteJid = '';

if (body.data) {
  // Ignorar mensajes enviados por el propio bot (evita loop infinito)
  if (body.data.key?.fromMe === true) {
    return [{ json: { skip: true } }];
  }

  const key = body.data.key || {};
  remoteJid = key.remoteJid || '';
  telefono = remoteJid.split('@')[0];
  mensaje = body.data.message?.conversation ||
            body.data.message?.extendedTextMessage?.text ||
            body.data.message?.imageMessage?.caption || '';
  nombre = body.data.pushName || '';
} else {
  telefono = body.telefono || body.from || '';
  mensaje = body.mensaje || body.message || body.text || '';
  nombre = body.nombre || body.pushName || '';
  remoteJid = telefono ? telefono + '@s.whatsapp.net' : '';
}

// Sanitizar
telefono = String(telefono).replace(/[^0-9]/g, '');
mensaje = String(mensaje).trim().substring(0, 4096);
nombre = String(nombre).trim().substring(0, 150);

return [{
  json: {
    telefono: telefono,
    mensaje: mensaje,
    nombre: nombre || null,
    remoteJid: remoteJid
  }
}];

const items = $input.all();
const results = [];

for (const item of items) {
    const telefono = $node["Extraer y Sanitizar"].json.telefono;
    const respuesta = item.json.respuesta;

    const evolutionResponse = await this.helpers.httpRequest({
        method: "POST",
        url: "http://evolution:8080/message/sendText/timonws",
        headers: {
            "apikey": "evotimon2026",
            "Content-Type": "application/json"
        },
        body: {
            number: telefono,
            text: respuesta
        },
        json: true
    });

    results.push({
        json: {
            success: true,
            respuesta: respuesta,
            evolution_response: evolutionResponse,
            conversacion_id: item.json.conversacion_id,
            categoria: item.json.categoria
        }
    });
}

return results;
